function move(dt){
  const forward=new THREE.Vector3(-Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y)),right=new THREE.Vector3(Math.cos(player.rotation.y),0,-Math.sin(player.rotation.y)),dir=new THREE.Vector3();
