    if(keys.KeyA||keys.ArrowLeft)player.rotation.y+=turn*dt;
    if(keys.KeyD||keys.ArrowRight)player.rotation.y-=turn*dt;
    activeVehicle.rotation.y=player.rotation.y;
    if(keys.KeyW||keys.ArrowUp)dir.add(forward);
    if(keys.KeyS||keys.ArrowDown)dir.sub(forward);
    if(dir.lengthSq()){dir.normalize();const speed=(type==='tank'?6.2:type==='truck'?8.1:4.7)*dt;activeVehicle.position.addScaledVector(dir,speed);const dist=Math.hypot(activeVehicle.position.x,activeVehicle.position.z);if(dist>51){activeVehicle.position.x*=51/dist;activeVehicle.position.z*=51/dist}activeVehicle.position.y=terrainHeight(activeVehicle.position.x,activeVehicle.position.z)}
    player.position.copy(activeVehicle.position);
  }else{
    if(keys.KeyW||keys.ArrowUp)dir.add(forward);if(keys.KeyS||keys.ArrowDown)dir.sub(forward);if(keys.KeyD||keys.ArrowRight)dir.add(right);if(keys.KeyA||keys.ArrowLeft)dir.sub(right);
    if(dir.lengthSq()){dir.normalize();const speed=(keys.ShiftLeft?8:5.2)*dt;player.position.addScaledVector(dir,speed);const dist=Math.hypot(player.position.x,player.position.z);if(dist>51){player.position.x*=51/dist;player.position.z*=51/dist}player.position.y=terrainHeight(player.position.x,player.position.z)}
  }
