  if(!activeVehicle){gun.position.y=-.29+Math.sin(performance.now()*.012)*(dir.lengthSq()?.009:.003);if(keys.Space&&!player.userData.jumping){player.userData.jumping=true;player.userData.jumpStart=performance.now()}if(player.userData.jumping){const t=(performance.now()-player.userData.jumpStart)/440;if(t>=1)player.userData.jumping=false;else camera.position.y+=Math.sin(t*Math.PI)*1.7}}
}

